<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>Cập nhật đơn hàng đi</h1>        <input type="text" class="form-control" style="width: 300px" placeholder="Nhập mã vận chuyển" id="shipping_code" />       </section>    <br/>    <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                    <div id="example2_wrapper" class="dataTables_wrapper form-inline dt-bootstrap">                        <table id="example2" class="table table-bordered table-hover dataTable" role="grid" aria-describedby="example2_info">                            <thead>                                <tr role="row">                                                                           <th>Mã vận chuyển</th>                                    <th>Tên khách</th>                                    <th>Số DT</th>                                    <th>Địa chỉ</th>                                                                                               <th>Tổng tiền</th>                                                                                               <th>Cách giao hàng</th>                                                                                           </tr>                            </thead>                            <tbody></tbody>                              </table>                    </div>                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><h1 class="pageTitle">Cập nhật đơn hàng đi</h1><script src="/assets/admin/js/ion.sound.js"></script><script>    ion.sound({        sounds: [            {name: "success"},            {name: "fail"}        ],        path: "/assets/sounds/",        preload: true,        volume: 1.0    });    $('#shipping_code').keypress(function (e) {        if (e.keyCode == 13) {            var shipping_code = $(this).val();            if (shipping_code) {                $.post('<?php echo base_url() . ADMIN_URL ?>update_shipping/update', {shipping_code: shipping_code}, function (result) {                    if (result == 0) {                        ion.sound.play("fail");                    } else {                        ion.sound.play("success");                        $('tbody').append(result);                    }                    $('#shipping_code').val('');                });            }        }    });</script>